// @FIGURE_CODE_BEGIN
// ELEMENT SPEC (one line per element)
// box wireframe        -> 12 x CylinderGeometry(r=0.022) sienna #8B3A2A
// slice plane (active) -> PlaneGeometry(4,4) rot.y=+PI/2 + CanvasTexture (inferno Gaussian)
// slice plane (static) -> same, at z = +0.8
// manifold solid       -> TubeGeometry(CatmullRom, r=0.05) teal #9ED6D2, depthTest ON
// manifold dashed      -> ~21 short TubeGeometry dashes, depthTest OFF, renderOrder 1
// pierce dots          -> SphereGeometry(0.09) #2E7F85
// curve arrowhead      -> ConeGeometry(0.12,0.34) teal
// marginal panel       -> PlaneGeometry(4,4) + CanvasTexture(numeric marginal) + 4 black border tubes
// panel curve/dots/arrow -> tube + spheres + cone, offset +0.03 in world X
// observation ring     -> TorusGeometry(0.13,0.022)
// gray arrow           -> Cylinder + Cone  #B8B8B8
// posterior ribbon     -> BufferGeometry triangle strip + baseline tube, teal
// all text             -> addLabel (serif / italic, black)

const SIG = 0.35;
const f1 = z => 0.55 * z;
const f2 = z => 1.3 - 0.34 * z * z;
const Wp = (x1, x2, z) => new THREE.Vector3(z, x2, -x1);   // (x1,x2,z) -> world

const C_SIENNA = 0x8B3A2A, C_TEAL = 0x9ED6D2, C_TEALD = 0x2E7F85, C_GRAY = 0xB8B8B8;

/* ── inferno-ish LUT ─────────────────────────────────────────────── */
const STOPS = [
  [0.00, [12, 4, 5]], [0.15, [43, 15, 8]], [0.40, [107, 36, 18]],
  [0.68, [216, 122, 56]], [0.88, [248, 200, 146]], [1.00, [255, 246, 232]]
];
function lut(t) {
  t = Math.max(0, Math.min(1, t));
  for (let i = 1; i < STOPS.length; i++) {
    if (t <= STOPS[i][0]) {
      const a = STOPS[i - 1], b = STOPS[i];
      const u = (t - a[0]) / (b[0] - a[0]);
      return [a[1][0] + (b[1][0] - a[1][0]) * u,
              a[1][1] + (b[1][1] - a[1][1]) * u,
              a[1][2] + (b[1][2] - a[1][2]) * u];
    }
  }
  return STOPS[STOPS.length - 1][1];
}

/* ── canvases / textures ─────────────────────────────────────────── */
function sliceCanvas(z, N, ghost) {
  const cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d');
  const img = ctx.createImageData(N, N);
  const m1 = f1(z), m2 = f2(z), inv = 1 / (2 * SIG * SIG);
  for (let j = 0; j < N; j++) {
    const x2 = 2 - 4 * (j + 0.5) / N;
    for (let i = 0; i < N; i++) {
      const x1 = -2 + 4 * (i + 0.5) / N;
      const dx = x1 - m1, dy = x2 - m2;
      const v = Math.exp(-(dx * dx + dy * dy) * inv);
      const c = lut(Math.pow(v, 0.75));
      const k = ghost ? Math.min(1, v * 3.0) : 1;
      const o = (j * N + i) * 4;
      img.data[o] = c[0] * k; img.data[o + 1] = c[1] * k; img.data[o + 2] = c[2] * k;
      img.data[o + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return cv;
}
function sliceTexture(z, N, ghost) {
  const t = new THREE.CanvasTexture(sliceCanvas(z, N, ghost || false));
  t.colorSpace = THREE.SRGBColorSpace; t.minFilter = THREE.LinearFilter;
  return t;
}

function marginalTexture() {
  const N = 128, M = 161;
  const zs = [], ws = [];
  for (let k = 0; k < M; k++) { const z = -3.6 + 7.2 * k / (M - 1); zs.push(z); ws.push(Math.exp(-z * z / 2)); }
  const raw = new Float32Array(N * N); let mx = 0;
  const inv = 1 / (2 * SIG * SIG);
  for (let j = 0; j < N; j++) {
    const x2 = 2 - 4 * (j + 0.5) / N;
    for (let i = 0; i < N; i++) {
      const x1 = -2 + 4 * (i + 0.5) / N; let s = 0;
      for (let k = 0; k < M; k++) {
        const dx = x1 - 0.55 * zs[k], dy = x2 - (1.3 - 0.34 * zs[k] * zs[k]);
        s += ws[k] * Math.exp(-(dx * dx + dy * dy) * inv);
      }
      raw[j * N + i] = s; if (s > mx) mx = s;
    }
  }
  const cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d'); const img = ctx.createImageData(N, N);
  for (let p = 0; p < N * N; p++) {
    const c = lut(Math.pow(raw[p] / mx, 0.5));
    img.data[p * 4] = c[0]; img.data[p * 4 + 1] = c[1]; img.data[p * 4 + 2] = c[2]; img.data[p * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace;
  t.minFilter = THREE.LinearFilter;
  return t;
}

/* ── primitive helpers ───────────────────────────────────────────── */
function tubeBetween(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10, 1), mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function curveTube(pts, r, mat) {
  const c = new THREE.CatmullRomCurve3(pts);
  return new THREE.Mesh(new THREE.TubeGeometry(c, Math.max(12, pts.length * 2), r, 10, false), mat);
}
function cone(pos, dir, rad, len, mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 16), mat);
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}

/* ── groups ──────────────────────────────────────────────────────── */
const jointGroup = new THREE.Group();
const panelGroup = new THREE.Group();
const linkGroup  = new THREE.Group();
const postGroup  = new THREE.Group();

/* ── wireframe box ───────────────────────────────────────────────── */
const siennaMat = new THREE.MeshBasicMaterial({ color: C_SIENNA });
const BX = 3, BY = 2, BZ = 2;
