  Drag in the figure to orbit: the two slice planes really are stacked along the
  <i>z</i> axis and the teal curve f(<i>z</i>,ϕ) is a genuine 3D curve.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ELEMENT SPEC (one line per element)
// box wireframe          -> 12 x CylinderGeometry(r=0.020) sienna #8B3A2A
// slice plane (active)   -> PlaneGeometry(4,4) rot.y=+PI/2 + CanvasTexture (inferno Gaussian), regenerated per z
// slice plane (static)   -> same, fixed at z = +0.8
// manifold solid         -> TubeGeometry(CatmullRom, r=0.05) teal #9ED6D2, depthTest ON
// manifold dashed        -> ~20 short TubeGeometry dashes, depthTest OFF, renderOrder 1
// pierce dots            -> SphereGeometry(0.09) #2E7F85
// curve arrowhead        -> ConeGeometry(0.12,0.34) teal
// marginal panel         -> PlaneGeometry(4,4) + CanvasTexture(CPU marginal integral) + 4 black border tubes
// panel curve/dots/arrow -> tube + spheres + cone, offset +0.04 in world X
// observation ring       -> TorusGeometry(0.14,0.025)
// gray arrow             -> Cylinder + Cone  #B8B8B8
// posterior ribbon       -> indexed BufferGeometry strip + baseline tube + MAP tick, teal
// all text               -> addLabel (serif, italic math), black

const SIG = 0.35;                 // conditional noise sd
const MSIG = 0.40;                // slightly broadened kernel used for the marginal image
const f1 = z => 0.55 * z;
const f2 = z => 1.3 - 0.34 * z * z;
const Wp = (x1, x2, z) => new THREE.Vector3(z, x2, -x1);   // (x1,x2,z) -> world

const C_SIENNA = 0x8B3A2A, C_TEAL = 0x9ED6D2, C_TEALD = 0x2E7F85, C_GRAY = 0xB8B8B8;

/* ── inferno-ish LUT ─────────────────────────────────────────────── */
const STOPS = [
  [0.00, [30, 12, 8]], [0.12, [52, 18, 10]], [0.35, [110, 38, 18]],
  [0.60, [182, 82, 33]], [0.80, [231, 151, 82]], [0.93, [250, 214, 166]],
  [1.00, [255, 247, 236]]
];
function lut(t) {
  t = Math.max(0, Math.min(1, t));
  for (let i = 1; i < STOPS.length; i++) {
    if (t <= STOPS[i][0]) {
      const a = STOPS[i - 1], b = STOPS[i];
      const u = (t - a[0]) / (b[0] - a[0]);
      return [a[1][0] + (b[1][0] - a[1][0]) * u,
              a[1][1] + (b[1][1] - a[1][1]) * u,
              a[1][2] + (b[1][2] - a[1][2]) * u];
    }
  }
  return STOPS[STOPS.length - 1][1];
}

/* ── canvases / textures ─────────────────────────────────────────── */
function sliceCanvas(z, N, ghost) {
  const cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d');
  const img = ctx.createImageData(N, N);
  const m1 = f1(z), m2 = f2(z), inv = 1 / (2 * SIG * SIG);
  for (let j = 0; j < N; j++) {
    const x2 = 2 - 4 * (j + 0.5) / N;
    for (let i = 0; i < N; i++) {
      const x1 = -2 + 4 * (i + 0.5) / N;
      const dx = x1 - m1, dy = x2 - m2;
      const v = Math.exp(-(dx * dx + dy * dy) * inv);
      const c = lut(Math.pow(v, 0.70));
      const k = ghost ? Math.min(1, v * 3.0) : 1;
      const o = (j * N + i) * 4;
      img.data[o] = c[0] * k; img.data[o + 1] = c[1] * k; img.data[o + 2] = c[2] * k;
      img.data[o + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return cv;
}
function sliceTexture(z, N, ghost) {
  const t = new THREE.CanvasTexture(sliceCanvas(z, N, ghost || false));
  t.colorSpace = THREE.SRGBColorSpace; t.minFilter = THREE.LinearFilter;
  return t;
}

// Pr(x|phi) = integral Norm(x; f(z), s^2 I) Norm(z;0,1) dz  on a 160x160 grid.
function marginalTexture() {
  const N = 160, M = 241;
  const zs = [], ws = [];
  for (let k = 0; k < M; k++) { const z = -4.2 + 8.4 * k / (M - 1); zs.push(z); ws.push(Math.exp(-z * z / 2)); }
  const raw = new Float32Array(N * N); let mx = 0;
  const inv = 1 / (2 * MSIG * MSIG);
  for (let j = 0; j < N; j++) {
    const x2 = 2 - 4 * (j + 0.5) / N;
    for (let i = 0; i < N; i++) {
      const x1 = -2 + 4 * (i + 0.5) / N; let s = 0;
      for (let k = 0; k < M; k++) {
        const dx = x1 - 0.55 * zs[k], dy = x2 - (1.3 - 0.34 * zs[k] * zs[k]);
        s += ws[k] * Math.exp(-(dx * dx + dy * dy) * inv);
      }
      raw[j * N + i] = s; if (s > mx) mx = s;
    }
  }
  const cv = document.createElement('canvas'); cv.width = cv.height = N;
  const ctx = cv.getContext('2d'); const img = ctx.createImageData(N, N);
  for (let p = 0; p < N * N; p++) {
    const c = lut(Math.pow(raw[p] / mx, 0.32));   // low gamma -> broad bright banana ridge
    img.data[p * 4] = c[0]; img.data[p * 4 + 1] = c[1]; img.data[p * 4 + 2] = c[2]; img.data[p * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace;
  t.minFilter = THREE.LinearFilter;
  return t;
}

/* ── primitive helpers ───────────────────────────────────────────── */
function tubeBetween(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10, 1), mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function curveTube(pts, r, mat) {
  const c = new THREE.CatmullRomCurve3(pts);
  return new THREE.Mesh(new THREE.TubeGeometry(c, Math.max(12, pts.length * 2), r, 10, false), mat);
}
function cone(pos, dir, rad, len, mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 18), mat);
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}

/* ── groups ──────────────────────────────────────────────────────── */
const jointGroup = new THREE.Group();
const panelGroup = new THREE.Group();
const linkGroup  = new THREE.Group();
const postGroup  = new THREE.Group();

/* ── wireframe box ───────────────────────────────────────────────── */
const siennaMat = new THREE.MeshBasicMaterial({ color: C_SIENNA });
const BX = 3, BY = 2, BZ = 2;
{
  const cs = [];
  for (const sx of [-BX, BX]) for (const sy of [-BY, BY]) for (const sz of [-BZ, BZ]) cs.push([sx, sy, sz]);
  const key = c => c.join(',');
  const seen = new Set();
  for (const a of cs) for (const b of cs) {
    let diff = 0;
    for (let k = 0; k < 3; k++) if (a[k] !== b[k]) diff++;
    if (diff !== 1) continue;
    const k2 = [key(a), key(b)].sort().join('|');
    if (seen.has(k2)) continue; seen.add(k2);
    jointGroup.add(tubeBetween(new THREE.Vector3(...a), new THREE.Vector3(...b), 0.020, siennaMat));
  }
}

/* ── slice planes ────────────────────────────────────────────────── */
const Z_STATIC = 0.8;
let zActive = -1.2;

const planeGeom = new THREE.PlaneGeometry(4, 4);
function makeSlicePlane(z) {
  const mat = new THREE.MeshBasicMaterial({ map: sliceTexture(z, 96), side: THREE.DoubleSide });
  const m = new THREE.Mesh(planeGeom, mat);
  m.rotation.y = Math.PI / 2; m.position.x = z;
  return m;
}
const planeActive = makeSlicePlane(zActive);
const planeStatic = makeSlicePlane(Z_STATIC);
jointGroup.add(planeActive, planeStatic);
registerInteractive(planeActive, {
  title: 'Pr(x | z, ϕ)',
  tooltip: 'Conditional density on one z-slice',
  body: 'On a slice of fixed latent value z the data density is a simple spherical Gaussian, Norm(f(z,ϕ), σ²I) with σ = 0.35. The decoder network f(·,ϕ) only decides WHERE its centre sits in the x₁–x₂ plane.'
});

/* ── manifold curve f(z,ϕ) ───────────────────────────────────────── */
const tealMat = new THREE.MeshBasicMaterial({ color: C_TEAL });
const tealDashMat = new THREE.MeshBasicMaterial({ color: C_TEAL, depthTest: false, depthWrite: false });
const tealDotMat = new THREE.MeshBasicMaterial({ color: C_TEALD });

function manifoldPts(z0, z1, n) {
  const p = [];
  for (let i = 0; i < n; i++) { const z = z0 + (z1 - z0) * i / (n - 1); p.push(Wp(f1(z), f2(z), z)); }
  return p;
}
const solidCurve = curveTube(manifoldPts(-3, 3, 140), 0.05, tealMat);
solidCurve.renderOrder = 2;
jointGroup.add(solidCurve);
registerInteractive(solidCurve, {
  title: 'Mean manifold f(z,ϕ)',
  tooltip: 'The decoder output as z varies',
  body: 'As the scalar latent z sweeps the real line, the decoder output f(z,ϕ) traces a curved one-dimensional manifold through the two-dimensional data space. The nonlinearity of the network is what bends this line.'
});

// dashed overlay (ignores depth), covered by the solid pass wherever the curve is unoccluded
{
  const dash = 0.17, gap = 0.13;
  for (let z = -3; z < 3; z += dash + gap) {
    const z2 = Math.min(3, z + dash);
    const seg = curveTube(manifoldPts(z, z2, 5), 0.05, tealDashMat);
    seg.renderOrder = 1;
    jointGroup.add(seg);
  }
}
// arrowhead at z = +3
{
  const t = new THREE.Vector3(1, -0.68 * 3, -0.55).normalize();
  const tip = Wp(f1(3), f2(3), 3);
  jointGroup.add(cone(tip.clone().add(t.clone().multiplyScalar(0.16)), t, 0.12, 0.34, tealMat));
}
// pierce dots
const dotActive = new THREE.Mesh(new THREE.SphereGeometry(0.09, 16, 12), tealDotMat);
const dotStatic = new THREE.Mesh(new THREE.SphereGeometry(0.09, 16, 12), tealDotMat);
dotActive.renderOrder = 3; dotStatic.renderOrder = 3;
dotStatic.position.copy(Wp(f1(Z_STATIC), f2(Z_STATIC), Z_STATIC));
jointGroup.add(dotActive, dotStatic);

/* ── 2D marginal panel ───────────────────────────────────────────── */
const PC = new THREE.Vector3(6.0, -1.3, -4.6);              // panel centre (world)
const panelMat = new THREE.MeshBasicMaterial({ map: marginalTexture(), side: THREE.DoubleSide, transparent: true, opacity: 1 });
const panelMesh = new THREE.Mesh(planeGeom, panelMat);
panelMesh.rotation.y = Math.PI / 2; panelMesh.position.copy(PC);
panelGroup.add(panelMesh);
