/* ── inferno-ish LUT ─────────────────────────────────────────────── */
const STOPS = [
  [0.00, [30, 12, 8]], [0.12, [52, 18, 10]], [0.35, [110, 38, 18]],
  [0.60, [182, 82, 33]], [0.80, [231, 151, 82]], [0.93, [250, 214, 166]],
  [1.00, [255, 247, 236]]
];
function lut(t) {
  t = Math.max(0, Math.min(1, t));
  for (let i = 1; i < STOPS.length; i++) {
    if (t <= STOPS[i][0]) {
      const a = STOPS[i - 1], b = STOPS[i];
      const u = (t - a[0]) / (b[0] - a[0]);
      return [a[1][0] + (b[1][0] - a[1][0]) * u,
              a[1][1] + (b[1][1] - a[1][1]) * u,
              a[1][2] + (b[1][2] - a[1][2]) * u];
    }
  }
