/* ── z slider wiring ─────────────────────────────────────────────── */
const zInput = document.getElementById('zSlice');
const zVal = document.getElementById('zVal');
function setZ(z, fromUi) {
  zActive = z;
  planeActive.position.x = z;
  planeActive.material.map.dispose();
  planeActive.material.map = sliceTexture(z, 96);
  planeActive.material.needsUpdate = true;
  dotActive.position.copy(Wp(f1(z), f2(z), z));
  pDotActive.position.copy(Ppt(f1(z), f2(z)));
  planeStatic.visible = Math.abs(z - Z_STATIC) > 0.12;
  dotStatic.visible = planeStatic.visible;
  zVal.textContent = z.toFixed(2);
  if (!fromUi) zInput.value = String(z);
}
zInput.addEventListener('input', () => setZ(parseFloat(zInput.value), true));

/* ── posterior from a dragged observation ────────────────────────── */
function updatePosterior(x1, x2) {
  const w = new Array(RN); let mx = 0, best = 0;
  for (let i = 0; i < RN; i++) {
    const z = -3 + 6 * i / (RN - 1);
    const dx = x1 - f1(z), dy = x2 - f2(z);
    const v = Math.exp(-(dx * dx + dy * dy) / (2 * SIG * SIG)) * Math.exp(-z * z / 2);
    w[i] = v; if (v > mx) { mx = v; best = z; }
  }
  for (let i = 0; i < RN; i++) w[i] = mx > 0 ? w[i] / mx : 0;
  setRibbon(w);
  mapMark.position.set(best / 3 * RX, RH / 2, 0);
  ring.position.copy(Ppt(x1, x2));
  ring.visible = true;
  const first = !hasObs;
  hasObs = true;
  setInScene(postGroup, true);
  showLabel(L.post, true); showLabel(L.postZ, true);
  placePostGroup();
  let s = 0, m = 0;
  for (let i = 0; i < RN; i++) { const z = -3 + 6 * i / (RN - 1); s += w[i]; m += w[i] * z; }
  m /= s; let v2 = 0;
  for (let i = 0; i < RN; i++) { const z = -3 + 6 * i / (RN - 1); v2 += w[i] * (z - m) * (z - m); }
  v2 = Math.sqrt(v2 / s);
  document.getElementById('dragStat').innerHTML =
    `x = (${x1.toFixed(2)}, ${x2.toFixed(2)}) &nbsp; peak z ≈ ${best.toFixed(2)}, spread ≈ ${v2.toFixed(2)}`;
  if (first && view === 'marginal') applyView('marginal');
}
document.getElementById('btnClearObs').addEventListener('click', () => {
  hasObs = false; ring.visible = false; setInScene(postGroup, false);
  showLabel(L.post, false); showLabel(L.postZ, false);
  document.getElementById('dragStat').textContent = 'no observation';
});

/* ── dragging on the marginal panel ──────────────────────────────── */
const rc = new THREE.Raycaster();
const ndc = new THREE.Vector2();
let dragging = false;
function panelHit(ev) {
  if (!panelGroup.parent) return null;
  const r = canvas.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(ndc, camera);
  const h = rc.intersectObject(panelMesh, false)[0];
  if (!h) return null;
  return {
    x1: Math.max(-2, Math.min(2, -(h.point.z - PC.z))),
    x2: Math.max(-2, Math.min(2, h.point.y - PC.y))
  };
}
canvas.addEventListener('pointerdown', ev => {
  const p = panelHit(ev);
  if (p) { dragging = true; controls.enabled = false; updatePosterior(p.x1, p.x2); }
});
canvas.addEventListener('pointermove', ev => {
  if (!dragging) return;
  const p = panelHit(ev);
  if (p) updatePosterior(p.x1, p.x2);
});
window.addEventListener('pointerup', () => { dragging = false; controls.enabled = true; });

/* ── marginalize sweep animation ─────────────────────────────────── */
const ghostGroup = new THREE.Group();
jointGroup.add(ghostGroup);
const GHOSTN = 40;
const ghostTex = [];
let sweep = null;

function ghostPlane(k) {
  const z = -3 + 6 * k / (GHOSTN - 1);
  if (!ghostTex[k]) ghostTex[k] = sliceTexture(z, 48, true);
  const mat = new THREE.MeshBasicMaterial({
    map: ghostTex[k], transparent: true, depthWrite: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
    opacity: 0.55 * Math.exp(-z * z / 2) + 0.05
  });
  const m = new THREE.Mesh(planeGeom, mat);
  m.rotation.y = Math.PI / 2; m.position.x = z;
  return m;
}
function clearGhosts() {
  ghostGroup.children.forEach(c => c.material.dispose());
  ghostGroup.clear();
}
document.getElementById('btnSweep').addEventListener('click', () => {
  if (view !== 'both') applyView('both');
  clearGhosts();
  sweep = { t: 0, spawned: 0, phase: 'run' };
  panelMat.opacity = 0.12;
});
function updateSweep(dt) {
  if (!sweep) return;
  if (sweep.phase === 'run') {
    sweep.t += dt / 4.2;
    const p = Math.min(1, sweep.t);
    setZ(-3 + 6 * p);
    const want = Math.floor(p * GHOSTN);
    while (sweep.spawned < want) { ghostGroup.add(ghostPlane(sweep.spawned)); sweep.spawned++; }
    panelMat.opacity = 0.12 + 0.88 * p;
    if (p >= 1) { sweep.phase = 'fade'; sweep.t = 0; }
  } else {
    sweep.t += dt / 1.4;
    ghostGroup.children.forEach(c => { c.material.opacity *= 0.955; });
    if (sweep.t >= 1) { clearGhosts(); panelMat.opacity = 1; sweep = null; }
  }
}

/* ── guided steps ────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The joint distribution',
    text: 'A wireframe box holds the joint space (x₁, x₂, z). One vertical slice at fixed z carries a single Gaussian blob: Pr(x|z,ϕ) is just a spherical Gaussian centred on the decoder output f(z,ϕ).',
    view: 'joint', z: -1.2 },
  { title: 'Sweeping z moves the blob',
    text: 'Increase z and the blob slides along the teal curve — the nonlinear decoder warps the straight latent axis into a curved manifold through data space.',
    view: 'joint', z: 0.8 },
  { title: 'Marginalizing over z',
    text: 'Now accumulate every slice, weighted by the prior Pr(z) = Norm(0,1). The stack of Gaussians collapses along the z axis and smears into a single broad, arc-shaped density.',
    view: 'both', z: 3, sweep: true },
  { title: 'The intractable marginal',
    text: 'Pr(x|ϕ) is a complex, non-Gaussian density in the x₁–x₂ plane. Drag an observation on it: the posterior Pr(z|x,ϕ) beneath is sharp near the manifold and broad or bimodal elsewhere — this is what variational inference must approximate.',
    view: 'marginal' }
];
let stepIdx = -1;
let tween = null;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('narration').textContent = s.text;
  applyView(s.view);
  if (typeof s.z === 'number') tween = { from: zActive, to: s.z, t: 0 };
  if (s.sweep) document.getElementById('btnSweep').click();
}
document.getElementById('prevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('vJoint').addEventListener('click', () => applyView('joint'));
document.getElementById('vMarg').addEventListener('click', () => applyView('marginal'));
document.getElementById('vBoth').addEventListener('click', () => applyView('both'));

/* ── ticker ──────────────────────────────────────────────────────── */
let _prevT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _prevT) / 1000); _prevT = now;
  if (tween) {
    tween.t += dt / 0.8;
    const p = Math.min(1, tween.t), e = p * p * (3 - 2 * p);
    setZ(tween.from + (tween.to - tween.from) * e);
    if (p >= 1) tween = null;
  }
  updateSweep(dt);
}
tick();

/* ── initial state ───────────────────────────────────────────────── */
setZ(-1.2);
applyView('both', false);
showLabel(L.post, false); showLabel(L.postZ, false);
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.78 });
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

