function keyPoints() {
  const P = [];
  if (view !== 'marginal') {
    for (const sx of [-BX, BX]) for (const sy of [-BY, BY]) for (const sz of [-BZ, BZ])
      P.push(new THREE.Vector3(sx, sy, sz));
    P.push(Wp(f1(Z0), f2(Z0), Z0), Wp(f1(Z1) + 0.4, f2(Z1) - 0.5, Z1));
    P.push(L.x1.pos, L.x2.pos, L.z.pos, L.joint.pos);
  }
  if (view !== 'joint') {
    for (const a of [-2, 2]) for (const b of [-2, 2]) P.push(Ppt(a, b));
    P.push(L.px1.pos, L.px2.pos, L.pmarg.pos);
  }
  if (view === 'both') P.push(ARR_A, ARR_B, L.link.pos);
  if (hasObs) {
    postGroup.updateMatrixWorld(true);
    P.push(postGroup.localToWorld(new THREE.Vector3(-RX, 0, 0)));
    P.push(postGroup.localToWorld(new THREE.Vector3(RX, RH, 0)));
    P.push(L.post.pos.clone(), L.postZ.pos.clone());
  }
  return P;
}

function fitView(base) {
  setCameraView(base);                       // pose + provisional framing
  const pts = keyPoints();
  camera.updateMatrixWorld();
  const inv = camera.matrixWorldInverse;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  const v = new THREE.Vector3();
  for (const p of pts) {
    v.copy(p).applyMatrix4(inv);
    minX = Math.min(minX, v.x); maxX = Math.max(maxX, v.x);
    minY = Math.min(minY, v.y); maxY = Math.max(maxY, v.y);
  }
  const w = Math.max(1e-3, maxX - minX), h = Math.max(1e-3, maxY - minY);
  const frac = 0.88;
  const zoom = Math.min(2 * d * frac / h, 2 * d * aspect * frac / w);
  const e0 = new THREE.Vector3(), e1 = new THREE.Vector3(), e2 = new THREE.Vector3();
  camera.matrixWorld.extractBasis(e0, e1, e2);
  const tgt = controls.target.clone()
    .add(e0.multiplyScalar((minX + maxX) / 2))
    .add(e1.multiplyScalar((minY + maxY) / 2));
  setCameraView({ ...base, zoom, target: [tgt.x, tgt.y, tgt.z] });
  lastBase = base;
  userMoved = false;
}

